```python
#!/usr/bin/env python3
"""
Rename photos to the date they were taken: 2024-05-12_001.jpg

Date sources, in order of preference:
  1. EXIF DateTimeOriginal / DateTimeDigitized / DateTime
  2. A date embedded in the filename (e.g. IMG_20240512_143000.jpg)
  3. File modification time (turn off with --no-mtime-fallback)

Photos from the same day are numbered chronologically: 001, 002, ...
Dry run by default; pass --apply to actually rename.

Requires Pillow for EXIF:  pip install Pillow
(For .heic files also:      pip install pillow-heif)
"""

import argparse
import os
import re
import sys
from datetime import datetime
from pathlib import Path

IMAGE_EXT = {".jpg", ".jpeg", ".png", ".heic", ".heif", ".tif", ".tiff",
             ".webp", ".dng", ".cr2", ".nef", ".arw", ".raf", ".orf", ".rw2"}

EXIF_DATE_TAGS = (36867, 36868, 306)  # DateTimeOriginal, DateTimeDigitized, DateTime
DATE_FORMATS = ("%Y:%m:%d %H:%M:%S", "%Y-%m-%d %H:%M:%S", "%Y:%m:%d %H:%M")

# Matches 2024-05-12, 2024_05_12, 2024.05.12 and IMG_20240512_143000 style names.
NAME_DATE_RE = re.compile(
    r"((?:19|20)\d{2})[-_.]?(0[1-9]|1[0-2])[-_.]?(0[1-9]|[12]\d|3[01])"
    r"(?:[-_ T]?([01]\d|2[0-3])([0-5]\d)([0-5]\d))?"
)


def parse_exif_date(raw):
    if isinstance(raw, bytes):
        raw = raw.decode("ascii", "ignore")
    if not isinstance(raw, str):
        return None
    raw = raw.strip().strip("\x00")
    for fmt in DATE_FORMATS:
        try:
            return datetime.strptime(raw, fmt)
        except ValueError:
            pass
    return None


def exif_datetime(path):
    try:
        from PIL import Image
    except ImportError:
        return None

    if path.suffix.lower() in {".heic", ".heif"}:
        try:
            import pillow_heif
            pillow_heif.register_heif_opener()
        except ImportError:
            return None

    try:
        with Image.open(path) as im:
            exif = im.getexif()
            ifds = [exif]
            try:
                ifds.append(exif.get_ifd(0x8769))
            except Exception:
                pass
            for ifd in ifds:
                for tag in EXIF_DATE_TAGS:
                    dt = parse_exif_date(ifd.get(tag))
                    if dt:
                        return dt
    except Exception:
        return None
    return None


def filename_datetime(path):
    m = NAME_DATE_RE.search(path.stem)
    if not m:
        return None
    year, month, day, hh, mm, ss = m.groups()
    try:
        return datetime(int(year), int(month), int(day),
                        int(hh or 0), int(mm or 0), int(ss or 0))
    except ValueError:
        return None


def photo_datetime(path, mtime_fallback):
    dt = exif_datetime(path)
    if dt:
        return dt, "exif"
    dt = filename_datetime(path)
    if dt:
        return dt, "filename"
    if mtime_fallback:
        return datetime.fromtimestamp(path.stat().st_mtime), "mtime"
    return None, None


def collect(root, recursive):
    it = root.rglob("*") if recursive else root.iterdir()
    return sorted(p for p in it if p.is_file() and p.suffix.lower() in IMAGE_EXT)


def main():
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("folder", nargs="?", default=".", help="folder to process (default: .)")
    ap.add_argument("--apply", action="store_true", help="actually rename (default: dry run)")
    ap.add_argument("-r", "--recursive", action="store_true", help="recurse into subfolders")
    ap.add_argument("--no-mtime-fallback", action="store_true",
                    help="leave undated files alone instead of using modification time")
    args = ap.parse_args()

    root = Path(args.folder)
    if not root.is_dir():
        sys.exit(f"Not a folder: {root}")

    dated, skipped = [], []
    for path in collect(root, args.recursive):
        dt, source = photo_datetime(path, not args.no_mtime_fallback)
        if dt is None:
            skipped.append(path)
        else:
            dated.append((path, dt, source))

    dated.sort(key=lambda item: (item[1], item[0].name.lower()))

    sources = {p.resolve() for p, _, _ in dated}
    counters, plan = {}, []
    for path, dt, source in dated:
        day = dt.strftime("%Y-%m-%d")
        n = counters.get(day, 0)
        while True:
            n += 1
            target = path.with_name(f"{day}_{n:03d}{path.suffix.lower()}")
            # Never land on a file that isn't itself being renamed away.
            if not target.exists() or target.resolve() in sources:
                break
        counters[day] = n
        if target != path:
            plan.append((path, target, source))

    if not plan and not skipped:
        print("Nothing to do.")
        return

    verb = "Renaming" if args.apply else "Would rename"
    for src, dst, source in plan:
        print(f"{verb}: {src.name}  ->  {dst.name}   [{source}]")
    for path in skipped:
        print(f"Skipping (no date found): {path}")

    if not args.apply:
        print(f"\n{len(plan)} file(s) would be renamed. Re-run with --apply to do it.")
        return

    # Two-phase rename so files can never clobber each other.
    staged = []
    try:
        for i, (src, dst, _) in enumerate(plan):
            tmp = src.with_name(f".photo-rename-tmp-{os.getpid()}-{i}{src.suffix.lower()}")
            src.rename(tmp)
            staged.append((tmp, dst))
        for tmp, dst in staged:
            tmp.rename(dst)
    except Exception:
        for tmp, dst in staged:
            if tmp.exists() and not dst.exists():
                tmp.rename(dst)  # best-effort rollback
        raise

    print(f"\nRenamed {len(plan)} file(s).")


if __name__ == "__main__":
    main()
```

How it behaves:

- **Dry run first.** `python rename_photos.py` prints the mapping and changes nothing.
- **Then apply.** `python rename_photos.py --apply`
- **Collision-safe.** If `2024-05-12_001.jpg` already exists (and isn't itself being renamed), it uses `002`, `003`, etc. Renames happen in two phases via temp names, so no photo can overwrite another mid-run.
- **Honest fallbacks.** Photos with no EXIF date and no date in the filename get their modification time (`[mtime]` in the output) — use `--no-mtime-fallback` if you'd rather they be left untouched.
- **Subfolders:** add `-r` if the photos are nested.

Two caveats worth knowing before you run it: `[mtime]` dates are only as trustworthy as the files' timestamps (copies can lose them), and numbering is per-folder, so running with `-r` numbers the whole tree sequentially while `--apply` on each subfolder separately would restart at 001.
